        <section className="w-full max-w-md rounded-[2rem] border border-white/70 bg-white/50 px-10 py-14 text-center shadow-[0_20px_60px_rgba(72,99,110,0.08)] backdrop-blur-sm">
          <div className="mx-auto mb-8 h-2 w-2 rounded-full bg-[#9bb9c3]" />
          <h1 className="font-serif text-5xl font-normal tracking-[-0.03em] text-[#29414b]">Hello.</h1>
          <p className="mx-auto mt-5 max-w-xs text-base leading-7 text-[#71848b]">A quiet little welcome, just for you.</p>
        </section>
      </div>
    </main>
  )
}

export default function HelloLoud() {
  return (
    <main className="relative flex min-h-screen items-center justify-center overflow-hidden bg-[#ffef2f] p-8 text-[#171321]">
