      <div className="absolute -bottom-24 -right-16 h-80 w-80 rotate-12 bg-[#5b35f5]" />
      <div className="absolute left-10 top-1/2 h-5 w-40 -rotate-12 bg-[#16d9b3]" />
      <section className="relative w-full max-w-4xl -rotate-2 border-8 border-[#171321] bg-[#ff7048] p-8 shadow-[16px_16px_0_#171321] sm:p-14">
        <p className="mb-5 font-mono text-sm font-bold tracking-[0.25em]">A TINY GREETING, BIG ENERGY</p>
